const item = $input.first();
return [{
  json: {
    ...item.json,
    cfg: {
      // true: es wird nichts an Instagram gesendet, die Antwort kommt nur per ntfy zur Ansicht.
      testModus: true,
      // Nicht leer: Nur diese Instagram-Nutzer-IDs (IGSID) bekommen echte Antworten, alle anderen nur den Probelauf per ntfy.
      erlaubteNutzer: [],
      graphUrl: 'https://graph.facebook.com/v23.0',
      igUserId: 'CHANGE-ME-IG-USER-ID',
      appSecret: 'CHANGE-ME-APP-SECRET',
      verifyToken: 'CHANGE-ME-VERIFY-TOKEN',
      ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
      ntfyTopic: 'instagram',
      wissensprofil: 'ausbildung',
      wartezeitSekunden: 8,
      verlaufNachrichten: 12,
      uebernahmeStunden: 12,
      maxAntwortenProStunde: 6,
      maxBytesProNachricht: 900,
      zustandsDatei: '/home/node/.n8n/instagram-dm-zustand.json',
      erlaubteDomains: ['dlrg.de', 'dlrg.org', 'dlrg-jugend.de', 'instagram.com', 'whatsapp.com'],
      kiHinweis: '🤖 Automatische Antwort der KI. Wenn du lieber mit einem Menschen schreiben möchtest, antworte einfach mit „Mensch“.',
      uebergabeText: 'Danke für deine Nachricht! Das kann ich hier nicht abschließend beantworten. Jemand aus dem Team meldet sich persönlich bei dir.',
      ohneTextAntwort: 'Danke für deine Nachricht! Bilder, Sprachnachrichten und Dateien kann ich leider nicht lesen. Schreib mir deine Frage bitte kurz als Text.'
    }
  },
  binary: item.binary
}];

const crypto = require('crypto');
const fs = require('fs');

const item = $input.first();
const json = item.json;
const cfg = json.cfg;
const jetzt = Date.now();

// Meta ruft denselben Pfad mit GET (Webhook-Verifizierung) und mit POST (Ereignisse) auf.
// Nur POSTs tragen den Rohtext (rawBody) als Binärdatei.
const istPost = !!(item.binary && item.binary.data);
const platzhalter = (wert) => !wert || String(wert).startsWith('CHANGE-ME');

if (!istPost) {
  const q = json.query || {};
  const hub = q.hub || {};
  const modus = q['hub.mode'] ?? hub.mode;
  const token = q['hub.verify_token'] ?? hub.verify_token;
  const challenge = q['hub.challenge'] ?? hub.challenge;
  const ok = modus === 'subscribe' && !platzhalter(cfg.verifyToken) && token === cfg.verifyToken && challenge !== undefined;
  return [{ json: { art: 'verify', ok, challenge: String(challenge ?? '') } }];
}

if (platzhalter(cfg.appSecret) || platzhalter(cfg.igUserId)) {
  console.log('Konfiguration unvollständig: appSecret oder igUserId fehlt, Ereignis verworfen');
  return [];
}

const roh = await this.helpers.getBinaryDataBuffer(0, 'data');
const erwartet = Buffer.from('sha256=' + crypto.createHmac('sha256', cfg.appSecret).update(roh).digest('hex'));
const erhalten = Buffer.from(String((json.headers || {})['x-hub-signature-256'] || ''));
if (erwartet.length !== erhalten.length || !crypto.timingSafeEqual(erwartet, erhalten)) {
  console.log('Signatur ungültig, Ereignis verworfen');
  return [];
}

let daten;
try {
  daten = JSON.parse(roh.toString('utf8'));
} catch (err) {
  return [];
}
if (daten.object !== 'instagram') return [];

// Zustand liegt in einer Datei, nicht in den Workflow-Static-Data: Lange Läufe (KI) würden dort
// die Änderungen paralleler Läufe überschreiben. Lesen und Schreiben sind synchron und damit atomar.
function lesen() {
  try {
    return JSON.parse(fs.readFileSync(cfg.zustandsDatei, 'utf8'));
  } catch (err) {
    return {};
  }
}
const z = lesen();
for (const feld of ['letzte', 'mensch', 'senden', 'antworten']) z[feld] = z[feld] || {};
z.mids = z.mids || [];

const IGNORIERT = ['like_heart', 'reaction', 'share', 'story_mention', 'ig_reel', 'ig_post'];
const MENSCH = /\b(mensch|menschen|echte[rn]? (person|mitarbeiter\w*)|mitarbeiter(in)?|ansprechpartner(in)?)\b/i;
const ergebnis = [];

for (const eintrag of daten.entry || []) {
  for (const m of eintrag.messaging || []) {
    const msg = m.message;
    if (!msg || !msg.mid) continue;

    if (msg.is_echo) {
      // Echo einer von uns gesendeten Nachricht. Eigene API-Antworten stehen im Sendefenster, alles andere schrieb ein Mensch in der Instagram-App.
      const nutzer = m.recipient && m.recipient.id;
      if (nutzer && !(z.senden[nutzer] > jetzt)) {
        z.mensch[nutzer] = jetzt + cfg.uebernahmeStunden * 3600000;
        console.log(`Mensch hat in der App geantwortet, KI pausiert für ${nutzer}`);
      }
      continue;
    }

    const sender = m.sender && m.sender.id;
    if (!sender || sender === cfg.igUserId || msg.is_deleted) continue;
    if (z.mids.includes(msg.mid)) continue;
    z.mids.push(msg.mid);
    z.letzte[sender] = msg.mid;

    if (z.mensch[sender] > jetzt) {
      console.log(`KI pausiert für ${sender} (Mensch hat übernommen)`);
      continue;
    }
    const letzteStunde = (z.antworten[sender] || []).filter((t) => t > jetzt - 3600000);
    if (letzteStunde.length >= cfg.maxAntwortenProStunde) {
      console.log(`Antwort-Limit für ${sender} erreicht, Nachricht übergangen`);
      continue;
    }

    const text = String(msg.text || '').trim().slice(0, 2000);
    const anhaenge = (msg.attachments || []).map((a) => a.type);
    const probe = cfg.testModus === true || (cfg.erlaubteNutzer.length > 0 && !cfg.erlaubteNutzer.includes(sender));
    const basis = { art: 'nachricht', sender, mid: msg.mid, text, probe, notiz: '' };

    if (!text) {
      if (anhaenge.length === 0 || anhaenge.every((t) => IGNORIERT.includes(t))) continue;
      ergebnis.push({ json: { ...basis, modus: 'fest', antwort: cfg.ohneTextAntwort, notiz: `Nachricht ohne Text (${anhaenge.join(', ')})` } });
    } else if (text.length <= 60 && MENSCH.test(text)) {
      ergebnis.push({ json: { ...basis, modus: 'uebergabe', antwort: cfg.uebergabeText, notiz: 'Person möchte mit einem Menschen schreiben' } });
    } else {
      ergebnis.push({ json: { ...basis, modus: 'ki', antwort: '' } });
    }
  }
}

z.mids = z.mids.slice(-500);
const alt = jetzt - 7 * 86400000;
for (const feld of ['mensch', 'senden']) {
  for (const k of Object.keys(z[feld])) if (z[feld][k] < alt) delete z[feld][k];
}
const tmp = `${cfg.zustandsDatei}.${process.pid}.tmp`;
fs.writeFileSync(tmp, JSON.stringify(z));
fs.renameSync(tmp, cfg.zustandsDatei);

return ergebnis;

// Nach der Wartezeit nur die neueste Nachricht je Person beantworten. Der Verlauf aus der Graph API enthält die früheren Nachrichten.
const fs = require('fs');
const cfg = $('Konfiguration').first().json.cfg;
let z = {};
try {
  z = JSON.parse(fs.readFileSync(cfg.zustandsDatei, 'utf8'));
} catch (err) {
  z = {};
}
const letzte = z.letzte || {};
return $input.all().filter(({ json }) => letzte[json.sender] === json.mid);

const nachricht = $('Noch die neueste Nachricht?').item.json;
const cfg = $('Konfiguration').first().json.cfg;

const berlin = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', dateStyle: 'short', timeStyle: 'short' });
const liste = (($json.data && $json.data[0] && $json.data[0].messages && $json.data[0].messages.data) || []).slice().reverse();
if ($json.error) console.log(`Verlauf nicht lesbar, Antwort ohne Verlauf: ${JSON.stringify($json.error).slice(0, 200)}`);

const history = liste
  .filter((m) => m.id !== nachricht.mid)
  .map((m) => ({
    from: m.from && m.from.id === cfg.igUserId ? 'DLRG Andernach (Verein)' : 'Anfragende Person',
    date: m.created_time ? berlin.format(new Date(m.created_time)) : '',
    text: String(m.message || '').trim() || '[Bild, Sprachnachricht oder Anhang]',
  }));
// Die aktuelle Nachricht steht schon im Verlauf, wenn die API sie mit anderer ID liefert.
const letzter = history[history.length - 1];
if (letzter && letzter.from === 'Anfragende Person' && letzter.text === nachricht.text) history.pop();

const payload = {
  channel: 'instagram',
  profile: cfg.wissensprofil,
  history: history.slice(-cfg.verlaufNachrichten),
  mail: { from: 'Anfragende Person', date: berlin.format(new Date()), text: nachricht.text },
};
return { json: { ...nachricht, payloadB64: Buffer.from(JSON.stringify(payload)).toString('base64') } };

const nachricht = $('LLM-Eingabe bauen').item.json;
const cfg = $('Konfiguration').first().json.cfg;
const { payloadB64, ...basis } = nachricht;

function uebergabe(notiz, text) {
  return { json: { ...basis, modus: 'uebergabe', antwort: text || cfg.uebergabeText, notiz } };
}

let parsed = null;
try {
  parsed = JSON.parse(String($json.stdout || '').trim().split('\n').pop());
} catch (err) {
  parsed = null;
}
if (!parsed || !parsed.ok) {
  const detail = parsed && parsed.error
    ? `${parsed.error.code}: ${parsed.error.message}`
    : String($json.stderr || $json.error || 'keine Ausgabe von ollama-pc/cli.js').trim();
  return uebergabe(`Ollama-Fehler, bitte selbst antworten: ${detail}`);
}

// Markdown hat im Chat keinen Nutzen.
let reply = String(parsed.reply || '')
  .replace(/\*\*([^*]+)\*\*/g, '$1')
  .replace(/^\s{0,3}#{1,6}\s+/gm, '')
  .replace(/^\s*\*\s+/gm, '- ')
  .trim();

const marker = /\[\s*(?:ÜBERGABE|UEBERGABE)\s*:?\s*([^\]]*)\]/i.exec(reply);
if (marker) {
  const grund = marker[1].trim() || 'ohne Angabe';
  const davor = reply.replace(marker[0], '').trim();
  // Text vor der Markierung (z. B. Notruf-Hinweis) wird gesendet, sonst der feste Übergabetext.
  return uebergabe(`KI übergibt: ${grund}`, davor);
}

const platzhalter = reply.match(/\[[A-ZÄÖÜ][A-ZÄÖÜ ]{2,}:[^\]]*\]/);
if (platzhalter) return uebergabe(`Antwort enthielt Platzhalter ${platzhalter[0].slice(0, 80)}, nicht gesendet`);
if (!reply) return uebergabe('Leere KI-Antwort');
if (/\b\d{2}_[a-z0-9_]+\.md\b/i.test(reply)) return uebergabe('Antwort nannte einen internen Dateinamen statt eines Links, nicht gesendet');

// Nur Links und Adressen des Vereins dürfen vorkommen, das Modell darf keine erfinden.
const erlaubt = (host) => cfg.erlaubteDomains.some((d) => host === d || host.endsWith(`.${d}`));
const hosts = [
  ...(reply.match(/https?:\/\/[^\s)>\]]+/gi) || []).map((u) => u.replace(/^https?:\/\//i, '').split(/[/?#:]/)[0]),
  ...(reply.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g) || []).map((a) => a.split('@')[1]),
  ...(reply.match(/\bwww\.[\w-]+(?:\.[\w-]+)+/gi) || []).map((u) => u.replace(/^www\./i, '')),
].map((h) => h.toLowerCase().replace(/[.,;:!?]+$/, ''));
const fremd = hosts.filter((h) => !erlaubt(h));
if (fremd.length) return uebergabe(`Antwort enthielt nicht erlaubte Adresse(n): ${[...new Set(fremd)].join(', ')}`);

return { json: { ...basis, modus: 'ki', antwort: reply } };

const fs = require('fs');
const cfg = $('Konfiguration').first().json.cfg;
const jetzt = Date.now();

function lesen() {
  try {
    return JSON.parse(fs.readFileSync(cfg.zustandsDatei, 'utf8'));
  } catch (err) {
    return {};
  }
}

// Teilt an Absätzen, dann an Sätzen, zuletzt hart. Instagram erlaubt höchstens 1000 Byte je Textnachricht.
function teile(text, maxBytes) {
  const bytes = (s) => Buffer.byteLength(s, 'utf8');
  const stuecke = [];
  const zusammen = (teile, trenner) => {
    const aus = [];
    let aktuell = '';
    for (const t of teile) {
      const kandidat = aktuell ? aktuell + trenner + t : t;
      if (bytes(kandidat) <= maxBytes) aktuell = kandidat;
      else {
        if (aktuell) aus.push(aktuell);
        aktuell = t;
      }
    }
    if (aktuell) aus.push(aktuell);
    return aus;
  };
  for (const absatz of zusammen(text.split(/\n{2,}/), '\n\n')) {
    if (bytes(absatz) <= maxBytes) {
      stuecke.push(absatz);
      continue;
    }
    for (const satz of zusammen(absatz.split(/(?<=[.!?])\s+/), ' ')) {
      if (bytes(satz) <= maxBytes) stuecke.push(satz);
      else {
        let rest = Array.from(satz);
        while (rest.length) {
          let n = rest.length;
          while (bytes(rest.slice(0, n).join('')) > maxBytes) n -= 1;
          stuecke.push(rest.slice(0, n).join(''));
          rest = rest.slice(n);
        }
      }
    }
  }
  return zusammen(stuecke, '\n\n');
}

const z = lesen();
for (const feld of ['mensch', 'senden', 'antworten']) z[feld] = z[feld] || {};
const ergebnis = [];
let geaendert = false;

for (const { json: n } of $input.all()) {
  const text = [String(n.antwort || '').trim(), cfg.kiHinweis].filter(Boolean).join('\n\n');
  if (!text) continue;

  if (n.probe) {
    ergebnis.push({ json: { ...n, nachrichtText: text } });
    continue;
  }

  // Vor dem Senden eintragen: Das Echo unserer eigenen Nachricht darf keine "Mensch hat übernommen"-Sperre auslösen.
  z.senden[n.sender] = jetzt + 90000;
  z.antworten[n.sender] = [...(z.antworten[n.sender] || []).filter((t) => t > jetzt - 3600000), jetzt];
  if (n.modus === 'uebergabe') z.mensch[n.sender] = jetzt + cfg.uebernahmeStunden * 3600000;
  geaendert = true;

  const stuecke = teile(text, cfg.maxBytesProNachricht);
  stuecke.forEach((stueck, index) => ergebnis.push({ json: { ...n, nachrichtText: stueck, teil: index + 1, teile: stuecke.length } }));
}

if (geaendert) {
  const tmp = `${cfg.zustandsDatei}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(z));
  fs.renameSync(tmp, cfg.zustandsDatei);
}
return ergebnis;

// Eine ntfy-Meldung je Nachricht, bei der ein Mensch handeln muss: Übergabe, Anhang ohne Text oder Sendefehler.
const gesendet = $('Senden vorbereiten').all();
const antworten = $input.all();
const nachMid = new Map();

antworten.forEach((antwort, index) => {
  const n = (gesendet[index] && gesendet[index].json) || {};
  const eintrag = nachMid.get(n.mid) || { n, fehler: [] };
  if (!antwort.json.message_id) {
    const err = antwort.json.error;
    eintrag.fehler.push(err && err.message ? err.message : typeof err === 'string' ? err : 'keine message_id in der Antwort');
  }
  nachMid.set(n.mid, eintrag);
});

const meldungen = [];
for (const { n, fehler } of nachMid.values()) {
  if (!fehler.length && !n.notiz) continue;
  const zeilen = [`Person ${n.sender}`, `Schrieb: ${n.text || '(kein Text)'}`];
  if (n.notiz) zeilen.push(`Grund: ${n.notiz}`);
  if (fehler.length) zeilen.push(`SENDEFEHLER: ${fehler.join(' | ')}`);
  else zeilen.push(`Gesendet: ${n.antwort}`);
  meldungen.push({
    json: {
      titel: fehler.length ? 'Instagram-DM: Senden fehlgeschlagen' : 'Instagram-DM: Uebergabe an Mensch',
      prioritaet: fehler.length ? 'high' : 'default',
      tags: fehler.length ? 'x' : 'speech_balloon',
      text: zeilen.join('\n'),
    },
  });
}
return meldungen;
